(() => {
    const rootSelector = '[data-p10-blog-editorial]';
      const openRootSelector = `${rootSelector}.is-filter-open`;
        const focusableSelector = [
            'a[href]',
                'button:not([disabled])',
                    'input:not([disabled])',
                        'select:not([disabled])',
                            'textarea:not([disabled])',
                                '[tabindex]:not([tabindex="-1"])',
                                  ].join(',');
                                    const mobileQuery = window.matchMedia('(max-width: 749px)');
                                      const states = new Map();
                                        let previousOverflow = '';
                                          let scrollLocked = false;

                                            const syncDocumentLock = () => {
                                                const documentElement = document.documentElement;
                                                    const hasOpenRoot = Boolean(document.querySelector(openRootSelector));

                                                        if (hasOpenRoot && !scrollLocked) {
                                                              previousOverflow = documentElement.style.overflow;
                                                                    documentElement.style.overflow = 'hidden';
                                                                          scrollLocked = true;
                                                                              }

                                                                                  documentElement.classList.toggle('p10-blog-filter-open', hasOpenRoot);

                                                                                      if (!hasOpenRoot && scrollLocked) {
                                                                                            documentElement.style.overflow = previousOverflow;
                                                                                                  previousOverflow = '';
                                                                                                        scrollLocked = false;
                                                                                                            }
                                                                                                              };

                                                                                                                const initializeRoot = (root) => {
                                                                                                                    if (states.has(root) || root.dataset.p10FilterInitialized === 'true') return;

                                                                                                                        const openButton = root.querySelector('[data-p10-filter-open]');
                                                                                                                            const closeButton = root.querySelector('[data-p10-filter-close]');
                                                                                                                                const drawer = root.querySelector('[data-p10-filter-drawer]');
                                                                                                                                    const backdrop = root.querySelector('[data-p10-filter-backdrop]');
                                                                                                                                        let previouslyFocused = null;

                                                                                                                                            if (!openButton || !closeButton || !drawer || !backdrop) return;

                                                                                                                                                const closeFilters = (restoreFocus = true) => {
                                                                                                                                                      openButton.setAttribute('aria-expanded', 'false');
                                                                                                                                                            drawer.setAttribute('aria-hidden', 'true');
                                                                                                                                                                  root.classList.remove('is-filter-open');
                                                                                                                                                                        syncDocumentLock();
                                                                                                                                                                              if (restoreFocus && previouslyFocused?.isConnected)
                                                                                                                                                                                      previouslyFocused?.focus();
                                                                                                                                                                                            previouslyFocused = null;
                                                                                                                                                                                                };

                                                                                                                                                                                                    const openFilters = () => {
                                                                                                                                                                                                          if (!mobileQuery.matches) return;
                                                                                                                                                                                                                previouslyFocused = document.activeElement;
                                                                                                                                                                                                                      openButton.setAttribute('aria-expanded', 'true');
                                                                                                                                                                                                                            drawer.setAttribute('aria-hidden', 'false');
                                                                                                                                                                                                                                  root.classList.add('is-filter-open');
                                                                                                                                                                                                                                        syncDocumentLock();
                                                                                                                                                                                                                                              drawer.querySelector(focusableSelector)?.focus();
                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                      const handleDocumentKeydown = (event) => {
                                                                                                                                                                                                                                                            const eventRoot = event.target.closest?.(openRootSelector);
                                                                                                                                                                                                                                                                  if (eventRoot && eventRoot !== root) return;
                                                                                                                                                                                                                                                                        if (!root.classList.contains('is-filter-open') || event.defaultPrevented)
                                                                                                                                                                                                                                                                                return;

                                                                                                                                                                                                                                                                                      if (event.key === 'Escape') {
                                                                                                                                                                                                                                                                                              event.preventDefault();
                                                                                                                                                                                                                                                                                                      closeFilters();
                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                          if (event.key !== 'Tab') return;
                                                                                                                                                                                                                                                                                                                                const focusableElements = [...drawer.querySelectorAll(focusableSelector)];
                                                                                                                                                                                                                                                                                                                                      const firstFocusable = focusableElements[0];
                                                                                                                                                                                                                                                                                                                                            const lastFocusable = focusableElements[focusableElements.length - 1];
                                                                                                                                                                                                                                                                                                                                                  if (!firstFocusable || !lastFocusable) return;

                                                                                                                                                                                                                                                                                                                                                        const focusIsOutside = !drawer.contains(document.activeElement);
                                                                                                                                                                                                                                                                                                                                                              const movingBeforeFirst =
                                                                                                                                                                                                                                                                                                                                                                      event.shiftKey &&
                                                                                                                                                                                                                                                                                                                                                                              (document.activeElement === firstFocusable || focusIsOutside);
                                                                                                                                                                                                                                                                                                                                                                                    const movingAfterLast =
                                                                                                                                                                                                                                                                                                                                                                                            !event.shiftKey &&
                                                                                                                                                                                                                                                                                                                                                                                                    (document.activeElement === lastFocusable || focusIsOutside);

                                                                                                                                                                                                                                                                                                                                                                                                          if (!movingBeforeFirst && !movingAfterLast) return;
                                                                                                                                                                                                                                                                                                                                                                                                                event.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                      (movingBeforeFirst ? lastFocusable : firstFocusable).focus();
                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                              const handleBreakpointChange = () => closeFilters(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                  const addMediaListener = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                        if (mobileQuery.addEventListener)
                                                                                                                                                                                                                                                                                                                                                                                                                                                mobileQuery.addEventListener('change', handleBreakpointChange);
                                                                                                                                                                                                                                                                                                                                                                                                                                                      else mobileQuery.addListener(handleBreakpointChange);
                                                                                                                                                                                                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                                                                                                                                                                                                              const removeMediaListener = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (mobileQuery.removeEventListener)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mobileQuery.removeEventListener('change', handleBreakpointChange);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else mobileQuery.removeListener(handleBreakpointChange);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const cleanup = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                closeFilters(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      openButton.removeEventListener('click', openFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            closeButton.removeEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  backdrop.removeEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.removeEventListener('keydown', handleDocumentKeydown);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              removeMediaListener();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    root.classList.remove('is-filter-enhanced');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          delete root.dataset.p10FilterInitialized;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                states.delete(root);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      syncDocumentLock();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    openButton.addEventListener('click', openFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          closeButton.addEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                backdrop.addEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.addEventListener('keydown', handleDocumentKeydown);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            addMediaListener();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  openButton.setAttribute('aria-expanded', 'false');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawer.setAttribute('aria-hidden', 'true');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              states.set(root, { cleanup });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    root.dataset.p10FilterInitialized = 'true';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          root.classList.add('is-filter-enhanced');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    openButton.removeEventListener('click', openFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          closeButton.removeEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                backdrop.removeEventListener('click', closeFilters);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.removeEventListener('keydown', handleDocumentKeydown);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            removeMediaListener();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const initializeWithin = (scope) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (scope.matches?.(rootSelector)) initializeRoot(scope);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            scope.querySelectorAll?.(rootSelector).forEach(initializeRoot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const cleanupWithin = (scope) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    states.forEach((state, root) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (scope === root || scope.contains?.(root)) state.cleanup();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.addEventListener('shopify:section:load', (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      initializeWithin(event.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.addEventListener('shopify:section:unload', (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cleanupWithin(event.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  initializeWithin(document);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (document.readyState === 'loading') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'DOMContentLoaded',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    () => initializeWithin(document),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { once: true },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
